def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    best_score = None
    best_versions = None

    def is_acyclic(edges):
        visiting = set()
        visited = set()

        def visit(name):
            if name in visiting:
                return False
            if name in visited:
                return True
            visiting.add(name)
            for dependency in edges.get(name, ()):
                if not visit(dependency):
                    return False
            visiting.remove(name)
            visited.add(name)
            return True

        return all(visit(name) for name in edges)

    def search(versions, constraints, edges):
        nonlocal best_score, best_versions

        for name, version in versions.items():
            if not all(low <= version <= high
                       for low, high in constraints.get(name, [])):
                return

        unresolved = sorted(name for name in constraints if name not in versions)
        if not unresolved:
            if not is_acyclic(edges):
                return
            score = tuple(versions.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(versions)
            return

        name = unresolved[0]
        if name not in packages:
            return

        for row in candidates(
                packages[name], constraints[name], blocked.get(name, []),
                pins.get(name)):
            version = row['version']
            next_versions = dict(versions)
            next_versions[name] = version
            next_constraints = {
                key: list(value) for key, value in constraints.items()
            }
            active_deps = []
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                dependency = dep['name']
                active_deps.append(dependency)
                next_constraints.setdefault(dependency, []).append(
                    (dep['min'], dep['max'])
                )
            next_edges = dict(edges)
            next_edges[name] = active_deps
            search(next_versions, next_constraints, next_edges)

    initial_constraints = {
        name: [(low, high)] for name, (low, high) in roots.items()
    }
    search({}, initial_constraints, {})

    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
